<script>
  let klass = null
  export { klass as class }
  export let scope = 'col' // Or row
  export let colspan = 1
  export let rowspan = 1

  let ariaColspan = colspan === 1 ? null : colspan
  let ariaRowspan = rowspan === 1 ? null : rowspan

  let role
  $: {
    if (scope === 'col') role = 'columnheader'
    else if (scope === 'row') role = 'rowheader'
    else if (scope === 'rowgroup') role = 'rowheader'
  }
</script>

<div
  {role}
  class="Cell Th {klass}"
  aria-colspan={ariaColspan}
  aria-rowspan={ariaRowspan}
  {...$$restProps}
>
  <slot />
</div>
